package app.bikriflow.mobile.util

data class ParsedOrder(val name: String = "", val phone: String = "", val address: String = "", val product: String = "", val variant: String = "", val quantity: Int = 1, val payment: String = "COD")
object OrderParser { private val phoneRegex = Regex("(?:\\+?88)?01[3-9]\\d{8}|\\+?\\d[\\d -]{8,14}\\d"); private val qtyRegex = Regex("(?i)(?:qty|quantity|pcs?|piece|x)\\s*[:=x-]?\\s*(\\d{1,3})"); fun parse(raw: String): ParsedOrder { if (raw.isBlank()) return ParsedOrder(); val lines = raw.lines().map { it.trim() }.filter { it.isNotBlank() }; fun valueFor(vararg keys: String): String { val match = lines.firstOrNull { line -> keys.any { k -> line.startsWith(k, ignoreCase = true) } } ?: return ""; return match.substringAfter(':', match.substringAfter('-', "")).trim() }; val phone = phoneRegex.find(raw)?.value?.replace(" ", "") ?: valueFor("phone", "mobile", "number", "ফোন", "মোবাইল"); val name = valueFor("name", "customer", "নাম"); val address = valueFor("address", "delivery address", "ঠিকানা"); val product = valueFor("product", "item", "পণ্য"); val variant = valueFor("size", "variant", "color", "colour", "সাইজ", "কালার"); val quantity = qtyRegex.find(raw)?.groupValues?.getOrNull(1)?.toIntOrNull() ?: valueFor("qty", "quantity", "পরিমাণ").filter { it.isDigit() }.toIntOrNull() ?: 1; val payment = if (raw.contains("advance", true) || raw.contains("paid", true)) "Advance" else "COD"; val inferredProduct = if (product.isBlank()) lines.firstOrNull { it != name && !it.contains(phone) && !it.startsWith("address", true) && !it.startsWith("name", true) && !it.startsWith("phone", true) }.orEmpty() else product; return ParsedOrder(name, phone, address, inferredProduct, variant, quantity.coerceAtLeast(1), payment) } }
